// Starfield
const starsGeometry = new THREE.BufferGeometry();
const starCount = 8000;
const starsPos = new Float32Array(starCount * 3);
const starsColors = new Float32Array(starCount * 3);
const starsSizes = new Float32Array(starCount);
for (let i = 0; i < starCount; i++) {
    const r = 1500 + Math.random() * 1000;
    const theta = Math.random() * Math.PI * 2;
    const phi = Math.acos(2 * Math.random() - 1);
    starsPos[i * 3] = r * Math.sin(phi) * Math.cos(theta);
    starsPos[i * 3 + 1] = r * Math.sin(phi) * Math.sin(theta);
    starsPos[i * 3 + 2] = r * Math.cos(phi);
    const starType = Math.random();
    let rCol, gCol, bCol;
    if (starType < 0.7) { rCol = 0.9 + Math.random() * 0.1; gCol = 0.9 + Math.random() * 0.1; bCol = 1.0; }
    else if (starType < 0.85) { rCol = 1.0; gCol = 0.8 + Math.random() * 0.2; bCol = 0.6 + Math.random() * 0.3; }
    else { rCol = 0.6 + Math.random() * 0.3; gCol = 0.7 + Math.random() * 0.2; bCol = 1.0; }
    starsColors[i * 3] = rCol;
    starsColors[i * 3 + 1] = gCol;
    starsColors[i * 3 + 2] = bCol;
    starsSizes[i] = 0.3 + Math.random() * 0.8;
}
starsGeometry.setAttribute('position', new THREE.BufferAttribute(starsPos, 3));
starsGeometry.setAttribute('color', new THREE.BufferAttribute(starsColors, 3));
const starsMaterial = new THREE.PointsMaterial({ size: 0.5, vertexColors: true, transparent: true, opacity: 0.8, sizeAttenuation: true });
const starField = new THREE.Points(starsGeometry, starsMaterial);
scene.add(starField);

