// === HELPERS: Texture & Color Gen ===
function createStarTexture(size) {
    const cvs = document.createElement('canvas');
    cvs.width = size; cvs.height = size;
    const ctx = cvs.getContext('2d');
    const grad = ctx.createRadialGradient(size / 2, size / 2, 0, size / 2, size / 2, size / 2);
    grad.addColorStop(0, 'rgba(255, 255, 255, 1)');
    grad.addColorStop(0.2, 'rgba(255, 248, 220, 0.9)');
    grad.addColorStop(0.5, 'rgba(255, 220, 150, 0.5)');
    grad.addColorStop(1, 'rgba(255, 180, 80, 0)');
    ctx.fillStyle = grad;
    ctx.fillRect(0, 0, size, size);
    const tex = new THREE.CanvasTexture(cvs);
    tex.minFilter = THREE.LinearFilter;
    return tex;
}

function createNoiseTexture(w, h, baseColor, noiseAmount) {
    const cvs = document.createElement('canvas');
    cvs.width = w; cvs.height = h;
    const ctx = cvs.getContext('2d');
    ctx.fillStyle = baseColor;
    ctx.fillRect(0, 0, w, h);
    const imgData = ctx.getImageData(0, 0, w, h);
    const data = imgData.data;
    for (let i = 0; i < data.length; i += 4) {
        const noise = (Math.random() - 0.5) * noiseAmount;
        data[i] = Math.max(0, Math.min(255, data[i] + noise));
        data[i + 1] = Math.max(0, Math.min(255, data[i + 1] + noise));
        data[i + 2] = Math.max(0, Math.min(255, data[i + 2] + noise));
    }
    ctx.putImageData(imgData, 0, 0);
    const tex = new THREE.CanvasTexture(cvs);
    tex.minFilter = THREE.LinearFilter;
    return tex;
}

function createRingTexture(innerRadiusRatio, color1, color2) {
    const cvs = document.createElement('canvas');
    cvs.width = 512; cvs.height = 512;
    const ctx = cvs.getContext('2d');
    const cx = 256, cy = 256;
    for (let i = 0; i < 50000; i++) {
        const angle = Math.random() * Math.PI * 2;
        const dist = innerRadiusRatio * 256 + Math.random() * (256 - innerRadiusRatio * 256);
        const x = cx + Math.cos(angle) * dist;
        const y = cy + Math.sin(angle) * dist;
        const alpha = 0.1 + Math.random() * 0.4;
        ctx.fillStyle = Math.random() > 0.5 ? color1 : color2;
        ctx.globalAlpha = alpha;
        ctx.fillRect(x, y, 1.5, 1.5);
    }
    ctx.globalAlpha = 1;
    const tex = new THREE.CanvasTexture(cvs);
    tex.minFilter = THREE.LinearFilter;
    return tex;
}

function createMoonTexture() {
    const cvs = document.createElement('canvas');
    cvs.width = 256; cvs.height = 256;
    const ctx = cvs.getContext('2d');
    ctx.fillStyle = '#aaa';
    ctx.fillRect(0, 0, 256, 256);
    for (let i = 0; i < 200; i++) {
        const x = Math.random() * 256;
        const y = Math.random() * 256;
        const r = 2 + Math.random() * 8;
        ctx.fillStyle = Math.random() > 0.5 ? '#888' : '#bbb';
        ctx.globalAlpha = 0.3;
        ctx.beginPath();
        ctx.arc(x, y, r, 0, Math.PI * 2);
        ctx.fill();
    }
    ctx.globalAlpha = 1;
    const tex = new THREE.CanvasTexture(cvs);
    tex.minFilter = THREE.LinearFilter;
    return tex;
}

function createAsteroidTexture() {
    return createNoiseTexture(64, 64, '#555', 80);
}

function getOrbitLineColor(name) {
    switch (name) {
        case 'Mercury': return 0x8899aa;
        case 'Venus': return 0xcc9966;
        case 'Earth': return 0x4488cc;
        case 'Mars': return 0xcc4444;
        case 'Jupiter': return 0xaa8866;
        case 'Saturn': return 0xddcc88;
        case 'Uranus': return 0x88ddcc;
        case 'Neptune': return 0x4466cc;
        default: return 0x444444;
    }
}

