// === PLANET DATA ===
const planetData = [
    { name: 'Mercury', radius: 2.4, distance: 45, speed: 4.15, color: '#8c8c8c', roughness: 0.9, metalness: 0.1, tilt: 0, textureNoise: 30 },
    { name: 'Venus', radius: 4.8, distance: 68, speed: 1.62, color: '#d4a574', roughness: 0.3, metalness: 0.4, tilt: 177.4, textureNoise: 20 },
    { name: 'Earth', radius: 5, distance: 95, speed: 1, color: '#2266aa', roughness: 0.6, metalness: 0.1, tilt: 23.5, hasMoon: true, textureNoise: 25 },
    { name: 'Mars', radius: 3.2, distance: 125, speed: 0.53, color: '#cc5533', roughness: 0.85, metalness: 0.1, tilt: 25.2, textureNoise: 40 },
    { name: 'Jupiter', radius: 14, distance: 200, speed: 0.084, color: '#d4a882', roughness: 0.4, metalness: 0.1, tilt: 3.1, hasBands: true, textureNoise: 15 },
    { name: 'Saturn', radius: 12, distance: 310, speed: 0.034, color: '#d4c594', roughness: 0.4, metalness: 0.15, tilt: 26.7, hasRings: true, textureNoise: 18 },
