    { name: 'Neptune', radius: 7.8, distance: 520, speed: 0.006, color: '#4466dd', roughness: 0.2, metalness: 0.3, tilt: 28.3, textureNoise: 20 }
];

const planets = [];
const orbitLines = [];
const orbitMeshes = [];
const group = new THREE.Group();
scene.add(group);

planetData.forEach((p, idx) => {
    // Planet mesh
    const planetGeo = new THREE.SphereGeometry(p.radius, 64, 64);
    let map;
    if (p.hasBands) {
        map = createNoiseTexture(512, 256, p.color, p.textureNoise);
    } else {
        map = createNoiseTexture(256, 256, p.color, p.textureNoise);
    }
    const planetMat = new THREE.MeshStandardMaterial({
        map: map,
        roughness: p.roughness,
        metalness: p.metalness,
        color: new THREE.Color(p.color)
    });
    const planet = new THREE.Mesh(planetGeo, planetMat);
    planet.castShadow = true;
    planet.receiveShadow = true;

    const planetPivot = new THREE.Object3D();
    group.add(planetPivot);
    planetPivot.add(planet);
    planet.position.set(p.distance, 0, 0);
    planet.rotation.z = THREE.MathUtils.degToRad(p.tilt);

    // Orbit ring
    const orbitGeo = new THREE.RingGeometry(p.distance - 0.5, p.distance + 0.5, 128);
    const orbitMat = new THREE.MeshBasicMaterial({ color: getOrbitLineColor(p.name), side: THREE.DoubleSide, transparent: true, opacity: 0.15 });
    const orbitMesh = new THREE.Mesh(orbitGeo, orbitMat);
    orbitMesh.rotation.x = Math.PI / 2;
    group.add(orbitMesh);

    // Orbit glow line
    const curvePoints = [];
    for (let i = 0; i <= 128; i++) {
        const a = (i / 128) * Math.PI * 2;
        curvePoints.push(new THREE.Vector3(Math.cos(a) * p.distance, 0, Math.sin(a) * p.distance));
    }
    const curve = new THREE.CatmullRomCurve3(curvePoints, true);
    const lineGeo = new THREE.TubeGeometry(curve, 128, 0.15, 8, true);
    const lineMat = new THREE.MeshBasicMaterial({ color: getOrbitLineColor(p.name), transparent: true, opacity: 0.3, blending: THREE.AdditiveBlending });
    const orbitLine = new THREE.Mesh(lineGeo, lineMat);
    orbitLine.rotation.x = Math.PI / 2;
    group.add(orbitLine);

    // Saturn rings
    if (p.hasRings && p.name === 'Saturn') {
        const ringGeo = new THREE.RingGeometry(p.radius * 1.4, p.radius * 2.8, 128);
        const ringTex = createRingTexture(0.5, '#d4c594', '#a08050');
        const ringMat = new THREE.MeshStandardMaterial({ map: ringTex, side: THREE.DoubleSide, transparent: true, opacity: 0.85, roughness: 0.6 });
        const ringMesh = new THREE.Mesh(ringGeo, ringMat);
        ringMesh.rotation.x = Math.PI / 2;
        planet.add(ringMesh);
    }

    // Uranus rings
    if (p.hasRings && p.name === 'Uranus') {
        const ringGeo = new THREE.RingGeometry(p.radius * 1.8, p.radius * 2.2, 64);
        const ringTex = createRingTexture(0.8, '#88ccdd', '#66aaee');
        const ringMat = new THREE.MeshStandardMaterial({ map: ringTex, side: THREE.DoubleSide, transparent: true, opacity: 0.6, roughness: 0.4 });
        const ringMesh = new THREE.Mesh(ringGeo, ringMat);
        ringMesh.rotation.x = Math.PI / 2;
        planet.add(ringMesh);
    }

    // Moon
    if (p.hasMoon) {
        const moonGeo = new THREE.SphereGeometry(1.2, 32, 32);
        const moonTex = createMoonTexture();
        const moonMat = new THREE.MeshStandardMaterial({ map: moonTex, roughness: 0.9, metalness: 0.0 });
        const moon = new THREE.Mesh(moonGeo, moonMat);
        moon.castShadow = true;
        moon.receiveShadow = true;
        const moonPivot = new THREE.Object3D();
        planet.add(moonPivot);
        moonPivot.add(moon);
        moon.position.set(p.radius + 8, 0, 0);
        moonPivot.userData = { isMoonPivot: true, moonSpeed: 4.0 };
    }

    // Store refs
    planets.push({
        mesh: planet,
        pivot: planetPivot,
        data: p,
        orbitMesh: orbitMesh,
        orbitLine: orbitLine
    });
    orbitLines.push(orbitLine);
    orbitMeshes.push(orbitMesh);
});

