// === UI LOGIC ===
let speedMultiplier = 1;
let showOrbits = true;
let focusedPlanet = 'Earth';
let isTransitioning = false;

const speedSlider = document.getElementById('speedSlider');
const speedValue = document.getElementById('speedValue');
const btnOrbitsOn = document.getElementById('btnOrbitsOn');
const btnOrbitsOff = document.getElementById('btnOrbitsOff');
const focusSelect = document.getElementById('focusSelect');

speedSlider.addEventListener('input', () => {
    speedMultiplier = parseFloat(speedSlider.value);
    speedValue.textContent = speedMultiplier.toFixed(1) + 'x';
});

function updateOrbitButtons() {
    if (showOrbits) {
        btnOrbitsOn.style.background = '#2255aa'; btnOrbitsOn.style.color = '#fff';
        btnOrbitsOff.style.background = '#1a2233'; btnOrbitsOff.style.color = '#8899aa';
    } else {
        btnOrbitsOn.style.background = '#1a2233'; btnOrbitsOn.style.color = '#8899aa';
        btnOrbitsOff.style.background = '#2255aa'; btnOrbitsOff.style.color = '#fff';
    }
    orbitLines.forEach(l => { l.visible = showOrbits; });
    orbitMeshes.forEach(m => { m.visible = showOrbits; });
}

btnOrbitsOn.addEventListener('click', () => { showOrbits = true; updateOrbitButtons(); });
btnOrbitsOff.addEventListener('click', () => { showOrbits = false; updateOrbitButtons(); });

focusSelect.addEventListener('change', () => {
    focusedPlanet = focusSelect.value;
    if (!focusedPlanet) {
        controls.target.set(0, 0, 0);
    } else if (focusedPlanet === 'Sun') {
        controls.target.set(0, 0, 0);
    }
});

// === CAMERA FOCUS LOGIC ===
function getFocusPosition() {
    if (!focusedPlanet || focusedPlanet === 'Sun') return new THREE.Vector3(0, 0, 0);
    const p = planets.find(pl => pl.data.name === focusedPlanet);
    if (!p) return new THREE.Vector3(0, 0, 0);
    const worldPos = new THREE.Vector3();
    p.mesh.getWorldPosition(worldPos);
    return worldPos;
}

let currentFocus = new THREE.Vector3(0, 0, 0);

// === ANIMATION ===
const clock = new THREE.Clock();

function animate() {
    const delta = clock.getDelta();
    const time = clock.getElapsedTime();

    // Sun pulsation
    const pulse = 1 + Math.sin(time * 1.5) * 0.03;
    sun.scale.setScalar(pulse);
    sunGlow.scale.set(90 * pulse, 90 * pulse, 1);
    sunGlow2.scale.set(140 * pulse, 140 * pulse, 1);

    // Sun light flicker
    sunLight.intensity = 2.5 + Math.sin(time * 3) * 0.1;

    // Planet orbits and rotation
    planets.forEach(p => {
        // Orbit
        p.pivot.rotation.y += (p.data.speed * 0.005) * speedMultiplier;
        // Self rotation
        p.mesh.rotation.y += (0.2 + p.data.speed * 0.1) * speedMultiplier;

        // Moon orbit
        p.mesh.children.forEach(child => {
            if (child.userData && child.userData.isMoonPivot) {
                child.rotation.y += child.userData.moonSpeed * 0.01 * speedMultiplier;
            }
        });
    });

    // Asteroid belt
    asteroidGroup.rotation.y += 0.0008 * speedMultiplier;
    asteroidGroup.children.forEach((a, i) => {
        a.rotation.x += 0.001 * (1 + (i % 3));
        a.rotation.z += 0.0008 * (1 + (i % 2));
    });

    // Starfield parallax
    starField.rotation.y += 0.00005;

    // Camera focus tracking
    const targetFocus = getFocusPosition();
    currentFocus.lerp(targetFocus, 0.05);
    controls.target.copy(currentFocus);

    controls.update();
    renderer.render(scene, camera);
}

renderer.setAnimationLoop(animate);

