function createBrick(x, y, z) {
  const mesh = new THREE.Mesh(
    new THREE.BoxGeometry(1, 1, 1),
    new THREE.MeshStandardMaterial({ color: 0xb74f2f, roughness: 0.95 })
  );
  mesh.position.set(x, y, z);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  scene.add(mesh);
}

function createQuestionBlock(x, y, z) {
  const geo = new THREE.BoxGeometry(1, 1, 1);
  const goldMat = new THREE.MeshStandardMaterial({ color: 0xffc400, metalness: 0.3, roughness: 0.4 });
  const canvas = document.createElement('canvas');
  canvas.width = 128;
  canvas.height = 128;
  const ctx = canvas.getContext('2d');
  ctx.fillStyle = '#ffc400';
  ctx.fillRect(0, 0, 128, 128);
  ctx.fillStyle = '#8a5d00';
  ctx.font = 'bold 90px monospace';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('?', 64, 64);
  const tex = new THREE.CanvasTexture(canvas);
  const faceMat = new THREE.MeshStandardMaterial({ map: tex, metalness: 0.3, roughness: 0.4 });
  const mesh = new THREE.Mesh(geo, [goldMat, goldMat, goldMat, goldMat, faceMat, faceMat]);
  mesh.position.set(x, y, z);
  mesh.castShadow = true;
  mesh.receiveShadow = true;
  scene.add(mesh);
  animatedBlocks.push({ mesh, baseY: y, offset: Math.random() * Math.PI * 2 });
}

function createPipe(x, z, h) {
  const g = new THREE.Group();
  const green = new THREE.MeshStandardMaterial({ color: 0x009933, roughness: 0.6 });
  const body = new THREE.Mesh(new THREE.CylinderGeometry(0.6, 0.6, h, 32), green);
  body.position.y = h / 2;
  body.castShadow = true;
  body.receiveShadow = true;
  g.add(body);
  const rim = new THREE.Mesh(new THREE.CylinderGeometry(0.72, 0.72, 0.35, 32), green);
  rim.position.y = h;
  rim.castShadow = true;
  rim.receiveShadow = true;
  g.add(rim);
  g.position.set(x, 0, z);
  scene.add(g);
}

function createCoin(x, y, z) {
  const group = new THREE.Group();
  const geo = new THREE.CylinderGeometry(0.25, 0.25, 0.04, 32);
  const mat = new THREE.MeshStandardMaterial({ color: 0xffd700, metalness: 0.8, roughness: 0.2 });
  const mesh = new THREE.Mesh(geo, mat);
  mesh.rotation.x = Math.PI / 2;
  mesh.castShadow = true;
  group.add(mesh);
  group.position.set(x, y, z);
  scene.add(group);
  animatedCoins.push({ group, speed: 0.08 + Math.random() * 0.04 });
